package io.github.bbadis.opuntiapad.core.language

import android.content.res.AssetManager
import org.json.JSONArray
import org.json.JSONObject

/** Languages and themes bundled in `assets/textmate/catalog.json` (generated by tools/). */
class LanguageCatalog(val languages: List<Language>, val themes: List<EditorTheme>) {

    val detector = LanguageDetector(languages)

    fun theme(id: String?, dark: Boolean): EditorTheme =
        themes.firstOrNull { it.id == id && it.dark == dark } ?: themes.first { it.dark == dark }

    companion object {
        const val CATALOG_PATH = "textmate/catalog.json"

        fun load(assets: AssetManager): LanguageCatalog {
            val json = JSONObject(assets.open(CATALOG_PATH).bufferedReader().use { it.readText() })
            val languages = json.getJSONArray("languages").objects().map { o ->
                Language(
                    id = o.getString("id"),
                    name = o.getString("name"),
                    scopeName = o.getString("scopeName"),
                    extensions = o.getJSONArray("extensions").strings(),
                    fileNames = o.getJSONArray("fileNames").strings(),
                    lineComment = o.optStringOrNull("lineComment"),
                    blockComment = o.optJSONArray("blockComment")?.strings()?.let { it[0] to it[1] },
                )
            }
            val themes = json.getJSONArray("themes").objects().map { o ->
                EditorTheme(o.getString("id"), o.getString("name"), o.getBoolean("dark"), o.getString("path"))
            }
            return LanguageCatalog(languages, themes)
        }

        private fun JSONArray.objects(): List<JSONObject> = (0 until length()).map { getJSONObject(it) }
        private fun JSONArray.strings(): List<String> = (0 until length()).map { getString(it) }
        private fun JSONObject.optStringOrNull(key: String): String? = if (isNull(key)) null else optString(key)
    }
}
